357	    /** The settings view of a sheet as it stood at the end of a day. */
358	    private SettingsView view(String id, History.SheetAsOf then) {
359	        LocalDate day = then.day();
360	        Function<String, BigDecimal> value = key -> then.setting(key, day).map(SettingValue::getValue).orElse(null);
361	        Map<String, Integer> gradeTerms = new TreeMap<>();
362	        for (String grade : List.of("A", "B", "C")) {
363	            then.setting("terms-" + grade, day).ifPresent(v -> gradeTerms.put(grade, v.getValue().intValue()));
364	        }
365	        int terms = then.setting("terms", day).map(v -> v.getValue().intValue()).orElse(SheetService.STARTING_TERMS);
366	        Map<String, Integer> gradeGraces = new TreeMap<>();
367	        Map<String, List<SettingValue>> graces = new TreeMap<>();
368	        for (String grade : List.of("A", "B", "C")) {
369	            then.setting("grace-" + grade, day).map(SettingValue::getValue)
370	                    .ifPresent(v -> gradeGraces.put(grade, v.intValue()));
371	            graces.put(grade, then.recorded("grace-" + grade));
372	        }
373	        Map<String, BigDecimal> gradeProofThresholds = new TreeMap<>();
374	        for (String grade : List.of("A", "B", "C")) {
375	            then.setting("proof-threshold-" + grade, day).map(SettingValue::getValue)
376	                    .ifPresent(v -> gradeProofThresholds.put(grade, v));
377	        }
378	        return SettingsView.of(value.apply("clerk-limit"), then.basis().floor(day), terms, then.basis().latePct(day),
379	                then.policyDate(), service.periodNumberingFrom(id), gradeTerms, then.basis().cap(),
380	                then.recorded("floor"), then.recorded("late-pct"), then.recorded("cap"),
381	                value.apply("proof-threshold"), service.permissions(id), service.graceDays(id),
382	                value.apply("note-threshold"), service.entryDate(id), gradeGraces, graces,
383	                gradeProofThresholds, service.pot(id), service.parent(id), service.fiscalStartMonth(id),
384	                service.alertThreshold(id),
385	                then.setting(Rounding.KEY, day).map(SettingValue::getValue).flatMap(Rounding::ofCode),
386	                then.recorded(Rounding.KEY), value.apply("review-threshold"), service.escalateAfter(id),
387	                service.reviewSla(id), service.proofKinds(id));
388	    }
